(()=>{const original=window.fetch.bind(window),base=new URL('./',location.href),prefix='/api/tools/knit';window.fetch=(input,options)=>{const url=new URL(input instanceof Request?input.url:input,location.href);if(url.origin===location.origin&&(url.pathname===prefix||url.pathname.startsWith(prefix+'/'))){const routed=new URL('./api/host'+url.pathname.slice(prefix.length)+url.search,base);input=input instanceof Request?new Request(routed,input):routed;}return original(input,options);};})();
